"use client";

import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import type { Agenda, Session } from "agenda-views/headless";
import { filterSessions, sortChronologically } from "agenda-views/headless";
import type { AgendaState, AgendaStatePatch } from "agenda-views/headless";
import { resolveAgendaState } from "agenda-views/headless";
import { AgendaProvider, useAgenda } from "@/lib/agenda-context";
import { useEventNow, useMediaQuery, useTheme } from "@/hooks/use-agenda";
import { AgendaList } from "@/components/ui/agenda-list";
import { DayTabs, SearchField, StageFilter, ThemeToggle, ViewToggle } from "@/components/ui/agenda-controls";
import { SessionSheet } from "@/components/ui/agenda-session-sheet";
import { GridLegend, TrackGrid } from "@/components/ui/agenda-track-grid";

type ViewMode = AgendaState["view"];

/**
 * Public entry: owns the provider so a consumer only passes data. The inner
 * component is where all the state lives, and it reads its agenda from context
 * exactly like any other consumer would.
 */
export type AgendaShellProps = {
  agenda: Agenda;
  /** Controlled state. Pair with `onStateChange`. */
  state?: AgendaState;
  /** Uncontrolled starting state. Invalid ids are dropped, not rendered blank. */
  defaultState?: AgendaStatePatch;
  onStateChange?: (next: AgendaState) => void;
  /** 12-hour clock. Default true. */
  hour12?: boolean;
  /** Vertical scale of the time grid, in px per minute. Default 2.3. */
  pxPerMinute?: number;
  /** Below this the grid is replaced by the chronological list. */
  gridBreakpoint?: string;
  /** Theme is usually the host app's job; off by default for embedded use. */
  showThemeToggle?: boolean;
  /** id for the `<main>`, e.g. a skip-link target owned by the host page. */
  mainId?: string;
  className?: string;
};

export function AgendaShell({ agenda, ...props }: AgendaShellProps) {
  return (
    <AgendaProvider agenda={agenda}>
      <AgendaShellInner {...props} />
    </AgendaProvider>
  );
}

function AgendaShellInner({
  state: controlledState,
  defaultState,
  onStateChange,
  hour12 = true,
  pxPerMinute,
  gridBreakpoint = "(min-width: 1024px)",
  showThemeToggle = false,
  mainId,
  className,
}: Omit<AgendaShellProps, "agenda">) {
  const index = useAgenda();
  const { days, stages, sessions } = index;
  const isWide = useMediaQuery(gridBreakpoint);
  const now = useEventNow(index);
  // unique per instance, so two agendas on one page do not fight over the id
  const nowAnchorId = useId();
  // every id this instance renders is namespaced by this
  const uid = useId();

  /* ------------------------------------------------------------- state */

  // Controlled when `state` is supplied, uncontrolled otherwise — the standard
  // React pattern, so a host can drive this from a router, storage, or nothing
  // at all. `resolveAgendaState` runs once so a stale link cannot render blank.
  const [uncontrolled, setUncontrolled] = useState(() =>
    resolveAgendaState(index, defaultState),
  );
  const state = controlledState ?? uncontrolled;

  const update = useCallback(
    (patch: AgendaStatePatch) => {
      const next = { ...state, ...patch };
      if (controlledState === undefined) setUncontrolled(next);
      onStateChange?.(next);
    },
    [controlledState, onStateChange, state],
  );

  const { dayId, stageIds, query, view: preferredView, selectedId } = state;
  const setDayId = useCallback((id: string) => update({ dayId: id }), [update]);
  const setStageIds = useCallback(
    (ids: string[]) => update({ stageIds: ids }),
    [update],
  );
  const setQuery = useCallback((q: string) => update({ query: q }), [update]);
  const setPreferredView = useCallback(
    (v: ViewMode) => update({ view: v }),
    [update],
  );
  const setSelectedId = useCallback(
    (id: string | null) => update({ selectedId: id }),
    [update],
  );

  const [theme, setTheme] = useTheme();

  const rootRef = useRef<HTMLDivElement>(null);
  const headerRef = useRef<HTMLDivElement>(null);

  /* --------------------------------------------------- sticky offset var */

  useEffect(() => {
    const node = headerRef.current;
    const root = rootRef.current;
    if (!node || !root) return;
    // set on this instance's root, not <html>: custom properties inherit, so
    // descendants still read it and a second agenda cannot clobber the first
    const sync = () =>
      root.style.setProperty("--agenda-sticky-top", `${node.offsetHeight}px`);
    sync();
    const observer = new ResizeObserver(sync);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  /* ------------------------------------------------------------- derived */

  const visible = useMemo(
    () => filterSessions(index, sessions, { dayId, stageIds, formats: [], query }),
    [index, sessions, dayId, stageIds, query],
  );

  const visibleStages = useMemo(
    () => (stageIds.length ? stages.filter((s) => stageIds.includes(s.id)) : stages),
    [stages, stageIds],
  );

  const counts = useMemo(() => {
    const map: Record<string, number> = {};
    for (const s of sessions) map[s.day] = (map[s.day] ?? 0) + 1;
    return map;
  }, [sessions]);

  // the grid only makes sense with room for lanes; below `lg` we always list
  const view: ViewMode = isWide ? preferredView : "list";
  const selected = useMemo(
    () => sessions.find((s) => s.id === selectedId) ?? null,
    [sessions, selectedId],
  );

  const onSelect = useCallback((session: Session) => setSelectedId(session.id), []);
  const onClose = useCallback(() => setSelectedId(null), []);

  const day = index.dayById.get(dayId)!;

  return (
    <div ref={rootRef} className="min-h-dvh bg-surface">
      {/* --------------------------------------------------- masthead (scrolls) */}
      <header className="print-hide masthead-bloom border-b border-line/60">
        <div className="mx-auto max-w-[1400px] px-5 pt-6 pb-4 sm:px-8 sm:pt-8">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <p className="text-[11px] font-semibold tracking-[0.18em] text-text-subtle uppercase">
              {index.agenda.days.length} days · {stages.length} stages ·{" "}
              {sessions.length} sessions
            </p>
            <h1 className="mt-1.5 text-2xl leading-[1.05] font-bold tracking-[-0.02em] text-balance text-text sm:text-4xl">
              Event programme
            </h1>
            <p className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-text-muted">
              <span className="font-medium text-text">
                {day.weekday} {day.short}
              </span>
              <span aria-hidden className="text-text-subtle">
                ·
              </span>
              <span>
                {visible.length === counts[dayId]
                  ? `${counts[dayId]} sessions`
                  : `${visible.length} of ${counts[dayId]} sessions`}
              </span>
              {stageIds.length > 0 && (
                <span className="rounded-full bg-surface-sunken px-2 py-0.5 text-[11px] font-semibold text-text-muted">
                  filtered
                </span>
              )}
            </p>
          </div>
          <div className="flex shrink-0 items-center gap-2">
            <ViewToggle value={preferredView} onChange={setPreferredView} />
            {showThemeToggle && <ThemeToggle theme={theme} onChange={setTheme} />}
          </div>
        </div>

        <div className="mt-5 sm:max-w-xs">
          <SearchField value={query} onChange={setQuery} resultCount={visible.length} />
        </div>
        </div>
      </header>

      {/*
        Only the controls stick. On a 390px screen a full sticky header would
        eat ~40% of the viewport; the title and search scroll away instead, and
        the sticky bar's measured height feeds the list's own sticky time rails.
      */}
      <div
        ref={headerRef}
        className="print-hide sticky top-0 z-40 border-b border-line bg-surface/85 py-3 backdrop-blur-xl"
      >
        <div className="mx-auto flex max-w-[1400px] flex-col gap-3 px-5 sm:flex-row sm:items-center sm:gap-4 sm:px-8">
          <div className="flex items-center gap-2">
            <DayTabs
              days={days}
              value={dayId}
              onChange={setDayId}
              counts={counts}
              idPrefix={uid}
            />
            {now?.dayId === dayId && <JumpToNowButton anchorId={nowAnchorId} />}
          </div>
          <div className="min-w-0 sm:ml-auto">
            <StageFilter stages={stages} value={stageIds} onChange={setStageIds} />
          </div>
        </div>
      </div>

      {/* -------------------------------------------------------------- body */}
      <main id={mainId} className="mx-auto max-w-[1400px] px-5 py-5 sm:px-8 sm:py-6">
        <div
          role="tabpanel"
          id={`${uid}panel-${dayId}`}
          aria-labelledby={`${uid}tab-${dayId}`}
          tabIndex={-1}
        >
          {visible.length === 0 ? (
            <EmptyState
              query={query}
              onReset={() => {
                setQuery("");
                setStageIds([]);
              }}
            />
          ) : view === "grid" ? (
            <>
              <TrackGrid
                sessions={visible}
                stages={visibleStages}
                now={now}
                dayId={dayId}
                selectedId={selectedId}
                onSelect={onSelect}
                hour12
                nowAnchorId={nowAnchorId}
              />
              <div className="mt-2">
                <GridLegend hour12 />
              </div>
              {/* the grid is a visual arrangement; this is the linear reading order */}
              <ScreenReaderAgenda sessions={visible} />
            </>
          ) : (
            // a single column of full-width rows is unreadable at 1400px —
            // cap the measure even though the same component serves mobile
            <div className="mx-auto max-w-3xl">
              <AgendaList
                sessions={visible}
                now={now}
                dayId={dayId}
                onSelect={onSelect}
                hour12
                nowAnchorId={nowAnchorId}
              />
            </div>
          )}
        </div>
      </main>

      <SessionSheet session={selected} now={now} onClose={onClose} hour12 />
    </div>
  );
}

/** Scrolls whichever view is mounted to its shared "now" anchor. */
function JumpToNowButton({ anchorId }: { anchorId: string }) {
  return (
    <button
      type="button"
      onClick={() =>
        document
          .getElementById(anchorId)
          ?.scrollIntoView({ block: "center", behavior: "smooth" })
      }
      className="flex h-11 shrink-0 items-center gap-2 rounded-2xl border border-line bg-surface-raised px-3.5 text-[13px] font-semibold text-text-muted shadow-(--shadow-card) transition hover:border-line-strong hover:text-text"
    >
      <span
        aria-hidden
        className="size-2 rounded-full bg-[var(--color-live)] ring-3 ring-[var(--color-live)]/20"
      />
      Now
    </button>
  );
}

function EmptyState({ query, onReset }: { query: string; onReset: () => void }) {
  return (
    <div className="lane-empty rounded-2xl border border-dashed border-line-strong px-6 py-20 text-center">
      <p className="text-sm font-medium text-text">
        {query ? `No sessions match “${query}”.` : "No sessions match these filters."}
      </p>
      <button
        type="button"
        onClick={onReset}
        className="mt-4 h-11 rounded-xl border border-line bg-surface-raised px-5 text-sm font-semibold text-text shadow-(--shadow-card) transition hover:border-line-strong hover:bg-surface-sunken"
      >
        Clear filters
      </button>
    </div>
  );
}

/**
 * The absolutely-positioned grid conveys time through geometry, which a screen
 * reader cannot follow. This mirrors the same sessions as a flat, ordered list.
 */
function ScreenReaderAgenda({ sessions: list }: { sessions: Session[] }) {
  const index = useAgenda();
  return (
    <ol className="sr-only">
      {sortChronologically(index, list).map((s) => (
        <li key={s.id}>
          {s.start} to {s.end}
          {s.stageId ? `, ${s.stageId.replace(/-/g, " ")} stage` : ", all stages"}:{" "}
          {s.title}
          {s.speakers.length > 0 &&
            `. With ${s.speakers.map((p) => p.name).join(", ")}`}
        </li>
      ))}
    </ol>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import type {
  EventNow,
  GridModel,
  PlacedSession,
  Session,
  SessionStatus,
  Stage,
} from "agenda-views/headless";
import { useAgenda } from "@/lib/agenda-context";
import {
  buildGrid,
  formatRange,
  formatTime,
  fromMinutes,
  sessionStatus,
  speakerSummary,
} from "agenda-views/headless";
import {
  ClockIcon,
  LiveBadge,
  PinIcon,
  SpeakerStack,
  cx,
  sessionAccent,
} from "@/components/ui/agenda-primitives";

/**
 * Desktop multi-track time grid.
 *
 * Rows are absolute-positioned by `offset * pxPerMinute` rather than laid out
 * in a CSS grid: sessions here start on 15/30/60-minute boundaries that do NOT
 * align to a single row unit, and a naive row grid collapses that structure.
 */

/**
 * px per minute. 2.3 is the smallest scale at which the shortest real session
 * (30 min → 69px) still fits a time row plus a two-line title, which is the
 * minimum needed to identify a talk without opening it. Overridable per
 * instance for denser or sparser programmes.
 */
export const DEFAULT_PX_PER_MINUTE = 2.3;
const HEADER_HEIGHT = 56;
/** hour ticks this close to the now-line are dropped so the labels can't collide */
const TICK_SUPPRESS_MINUTES = 18;

export type BlockDensity = {
  titleLines: string;
  speakers: boolean;
  location: boolean;
};

/** How much a block can show, purely as a function of its height. */
export function defaultDensity(minutes: number): BlockDensity {
  if (minutes < 30) return { titleLines: "clamp-1", speakers: false, location: false };
  if (minutes < 45) return { titleLines: "clamp-2", speakers: false, location: false };
  if (minutes < 60) return { titleLines: "clamp-2", speakers: true, location: false };
  if (minutes < 90) return { titleLines: "clamp-3", speakers: true, location: true };
  return { titleLines: "clamp-3", speakers: true, location: true };
}

type Props = {
  sessions: Session[];
  stages: Stage[];
  now: EventNow | null;
  dayId: string;
  selectedId: string | null;
  onSelect: (session: Session) => void;
  hour12: boolean;
  /** DOM id placed on the now-line, so an external control can scroll to it */
  nowAnchorId?: string;
  pxPerMinute?: number;
  density?: (minutes: number) => BlockDensity;
};

export function TrackGrid({
  sessions,
  stages,
  now,
  dayId,
  selectedId,
  onSelect,
  hour12,
  nowAnchorId,
  pxPerMinute = DEFAULT_PX_PER_MINUTE,
  density = defaultDensity,
}: Props) {
  const index = useAgenda();
  const blockIdPrefix = useId();
  const grid = buildGrid(sessions, stages);
  const scrollerRef = useRef<HTMLDivElement>(null);
  // the block currently under the pointer or keyboard focus, used to project
  // its span back onto the time gutter
  const [active, setActive] = useState<PlacedSession | null>(null);
  const nowMinutes = now && now.dayId === dayId ? now.minutes : null;
  const nowOffset =
    nowMinutes !== null &&
    nowMinutes >= grid.startMinutes &&
    nowMinutes <= grid.endMinutes
      ? nowMinutes - grid.startMinutes
      : null;

  // scroll the "now" line into view once, on the day that is actually running
  const scrolledFor = useRef<string | null>(null);
  useEffect(() => {
    if (nowOffset === null || scrolledFor.current === dayId) return;
    scrolledFor.current = dayId;
    scrollerRef.current?.scrollTo({
      top: Math.max(0, nowOffset * pxPerMinute - 120),
      behavior: "smooth",
    });
  }, [nowOffset, dayId, pxPerMinute]);

  if (!sessions.length) return null;

  const bodyHeight = grid.totalMinutes * pxPerMinute;

  return (
    <div
      ref={scrollerRef}
      className="print-full relative max-h-[calc(100dvh-var(--agenda-sticky-top,4rem)-2rem)] overflow-auto rounded-2xl border border-line bg-surface-raised shadow-(--shadow-card)"
    >
      <div
        className="relative grid"
        style={{
          gridTemplateColumns: `var(--agenda-gutter) repeat(${stages.length}, minmax(var(--agenda-lane-min), 1fr))`,
        }}
      >
        {/* ---------------------------------------------------- stage header */}
        <div
          className="sticky top-0 left-0 z-30 border-r border-b border-line bg-surface-raised"
          style={{ height: HEADER_HEIGHT }}
        />
        {stages.map((stage) => (
          <div
            key={stage.id}
            className={cx(
              // `sticky` already creates the containing block for the accent rule
              "sticky top-0 z-20 flex flex-col justify-center border-b border-line px-3.5",
              "bg-linear-to-b from-[var(--accent-tint)] to-surface-raised",
              accentFor(stage.accent),
            )}
            style={{ height: HEADER_HEIGHT }}
          >
            <span
              aria-hidden
              className="absolute inset-x-0 top-0 h-0.5 bg-[var(--accent)]"
            />
            <span className="flex items-center gap-2 text-sm font-semibold text-text">
              <span
                aria-hidden
                className="size-2 shrink-0 rounded-full bg-[var(--accent)] ring-3 ring-[var(--accent)]/20"
              />
              <span className="truncate">{stage.name}</span>
            </span>
            <span className="truncate pl-4 text-xs text-text-subtle">{stage.venue}</span>
          </div>
        ))}

        {/* ----------------------------------------------------- time gutter */}
        <div
          className="sticky left-0 z-20 border-r border-line bg-surface-raised"
          style={{ height: bodyHeight }}
        >
          {[...grid.hours, ...grid.halfHours]
            .filter(
              (minute) =>
                (nowMinutes === null ||
                  Math.abs(minute - nowMinutes) > TICK_SUPPRESS_MINUTES) &&
                // the active block writes its own start/end here instead
                (!active || !isEdgeOf(active, minute, grid.startMinutes)),
            )
            .map((minute) => (
              <div
                key={minute}
                className="absolute right-0 left-0 -translate-y-1/2 pr-2 text-right"
                style={{ top: (minute - grid.startMinutes) * pxPerMinute }}
              >
                <span
                  className={cx(
                    "font-mono tabular-nums",
                    minute % 60 === 0
                      ? "text-[11px] text-text-muted"
                      : "text-[10px] text-text-subtle/70",
                  )}
                >
                  {formatTime(fromMinutes(minute), hour12)}
                </span>
              </div>
            ))}

          {/* the hovered/focused block's exact span, written into the gutter */}
          {active && (
            <div
              className="absolute right-0 left-0 animate-fade-in"
              style={{
                top: active.offset * pxPerMinute,
                height: active.duration * pxPerMinute,
              }}
            >
              <span
                aria-hidden
                className="absolute top-0 bottom-0 right-1 w-0.5 rounded-full bg-[var(--color-brand)]"
              />
              <span className="absolute top-0 right-3 -translate-y-1/2 rounded bg-[var(--color-brand)] px-1 py-px font-mono text-[10px] leading-tight font-bold text-white tabular-nums">
                {formatTime(active.session.start, hour12)}
              </span>
              <span className="absolute right-3 bottom-0 translate-y-1/2 rounded bg-[var(--color-brand)] px-1 py-px font-mono text-[10px] leading-tight font-bold text-white tabular-nums">
                {formatTime(active.session.end, hour12)}
              </span>
            </div>
          )}
        </div>

        {/* ------------------------------------------------------ stage lanes */}
        {grid.lanes.map((lane) => (
          <div
            key={lane.stage.id}
            className={cx(
              "relative border-r border-line last:border-r-0",
              lane.items.length === 0 && "lane-empty",
            )}
            style={{ height: bodyHeight }}
          >
            <TimeRules grid={grid} pxPerMinute={pxPerMinute} />
            {lane.items.map((item) => (
              <GridBlock
                key={item.session.id}
                item={item}
                selected={item.session.id === selectedId}
                status={sessionStatus(index, item.session, now)}
                onSelect={onSelect}
                onActivate={setActive}
                hour12={hour12}
                pxPerMinute={pxPerMinute}
                density={density}
                idPrefix={blockIdPrefix}
              />
            ))}
          </div>
        ))}

        {/* --------------------------------------- plenary / all-stage bands */}
        {grid.fullWidth.map((item) => (
          <div
            key={item.session.id}
            className="pointer-events-none absolute right-0 left-[var(--agenda-gutter)] z-10 px-1.5 py-0.5"
            style={{
              top: HEADER_HEIGHT + item.offset * pxPerMinute,
              height: item.duration * pxPerMinute,
            }}
          >
            <button
              type="button"
              onClick={() => onSelect(item.session)}
              className="lane-empty pointer-events-auto flex size-full items-center justify-center gap-3 rounded-xl border border-dashed border-line-strong bg-surface-sunken/80 text-sm font-semibold tracking-wide text-text-muted transition hover:border-[var(--color-brand)] hover:text-text"
            >
              <span className="tracking-wide uppercase">{item.session.title}</span>
              <span className="font-mono text-xs tabular-nums">
                {formatRange(item.session.start, item.session.end, hour12)}
              </span>
            </button>
          </div>
        ))}

        {/* ------------------------------------------ active block guide lines */}
        {active && (
          <div
            aria-hidden
            className="pointer-events-none absolute right-0 left-[var(--agenda-gutter)] z-10 animate-fade-in"
            style={{
              top: HEADER_HEIGHT + active.offset * pxPerMinute,
              height: active.duration * pxPerMinute,
            }}
          >
            <span className="absolute top-0 right-0 left-0 border-t border-dashed border-[var(--color-brand)]/60" />
            <span className="absolute right-0 bottom-0 left-0 border-t border-dashed border-[var(--color-brand)]/60" />
          </div>
        )}

        {/* -------------------------------------------------------- now line */}
        {nowOffset !== null && (
          <div
            aria-hidden
            id={nowAnchorId}
            className="pointer-events-none absolute right-0 left-0 z-30 scroll-mt-40"
            style={{ top: HEADER_HEIGHT + nowOffset * pxPerMinute }}
          >
            <div className="relative h-px bg-[var(--color-live)]">
              {/* the badge lives in the gutter with the other times; nearby hour
                  ticks are suppressed rather than overlapped */}
              <span className="absolute -top-2 right-[calc(100%-var(--agenda-gutter)+2px)] rounded-full bg-[var(--color-live)] px-1.5 py-0.5 font-mono text-[10px] leading-none font-bold text-white tabular-nums shadow-sm">
                {formatTime(fromMinutes(nowMinutes!), hour12)}
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function accentFor(accent: Stage["accent"]) {
  return `accent-${accent}`;
}

/** True when `minute` is the start or end edge of the active block. */
function isEdgeOf(active: PlacedSession, minute: number, gridStart: number) {
  const top = gridStart + active.offset;
  return minute === top || minute === top + active.duration;
}

/**
 * Two rule weights. Solid on the hour, dotted on the half — most sessions in a
 * conference programme start on :30, and without a rule there the eye has
 * nothing to measure a block's top edge against.
 */
function TimeRules({
  grid,
  pxPerMinute,
}: {
  grid: GridModel;
  pxPerMinute: number;
}) {
  return (
    <>
      {grid.hours.map((minute) => (
        <div
          key={minute}
          aria-hidden
          className="absolute right-0 left-0 border-t border-line/70"
          style={{ top: (minute - grid.startMinutes) * pxPerMinute }}
        />
      ))}
      {grid.halfHours.map((minute) => (
        <div
          key={minute}
          aria-hidden
          className="absolute right-0 left-0 border-t border-dotted border-line/50"
          style={{ top: (minute - grid.startMinutes) * pxPerMinute }}
        />
      ))}
    </>
  );
}

function GridBlock({
  item,
  selected,
  status,
  onSelect,
  onActivate,
  hour12,
  pxPerMinute,
  density,
  idPrefix,
}: {
  item: PlacedSession;
  selected: boolean;
  status: SessionStatus;
  onSelect: (session: Session) => void;
  onActivate: (item: PlacedSession | null) => void;
  hour12: boolean;
  pxPerMinute: number;
  density: (minutes: number) => BlockDensity;
  idPrefix: string;
}) {
  const { stageById } = useAgenda();
  const { session, offset, duration, column, columns } = item;
  const fit = density(duration);
  const width = 100 / columns;
  const speakers = speakerSummary(session, 2);

  return (
    <button
      type="button"
