      >
        {session.format && (
          <span className="mr-1 text-[var(--accent-text)]">[{session.format}]</span>
        )}
        {session.title}
      </span>

      {fit.speakers && speakers && (
        <span className="mt-1.5 flex items-center gap-1.5">
          <SpeakerStack speakers={session.speakers} max={3} size={20} />
