"use client";

import { useEffect, useRef } from "react";
import type { EventNow, Session, SessionStatus } from "agenda-views/headless";
import { useAgenda } from "@/lib/agenda-context";
import {
  durationMinutes,
  formatDuration,
  formatTime,
  groupByStart,
  sessionStatus,
} from "agenda-views/headless";
import {
  FormatBadge,
  LiveBadge,
  PinIcon,
  SpeakerStack,
  StageBadge,
  cx,
  sessionAccent,
} from "@/components/ui/agenda-primitives";

/**
 * Mobile / narrow view: one chronological column.
 *
 * The desktop grid fails here because four lanes cannot fit in 390px without
 * either horizontal scrolling (which hides tracks) or 60px columns (which
 * truncate every title). Time becomes a sticky rail instead of an axis, and
 * concurrency is communicated by grouping rather than by column position.
 */

type Props = {
  sessions: Session[];
  now: EventNow | null;
  dayId: string;
  onSelect: (session: Session) => void;
  hour12: boolean;
  /** DOM id placed on the live time rail, for an external "jump to now" */
  nowAnchorId?: string;
};

export function AgendaList({
  sessions,
  now,
  dayId,
  onSelect,
  hour12,
  nowAnchorId,
}: Props) {
  const index = useAgenda();
  const groups = groupByStart(index, sessions);
  const liveRef = useRef<HTMLDivElement>(null);
  const scrolledFor = useRef<string | null>(null);

  const nowMinutes = now && now.dayId === dayId ? now.minutes : null;
  // only the first live block gets the scroll anchor
  const liveIndex = groups.findIndex((g) =>
    g.sessions.some((s) => sessionStatus(index, s, now) === "live"),
  );

  // Jump to the current time block once, on the running day. `liveIndex` is in
  // the deps because `now` arrives a tick after mount — keying on the day alone
  // would miss the render where the anchor first exists. rAF lets the sticky
  // rails settle so the target does not land underneath them.
  useEffect(() => {
    if (liveIndex < 0 || !liveRef.current || scrolledFor.current === dayId) return;
    scrolledFor.current = dayId;
    const node = liveRef.current;
    const frame = requestAnimationFrame(() =>
      node.scrollIntoView({ block: "center", behavior: "smooth" }),
    );
    return () => cancelAnimationFrame(frame);
  }, [dayId, liveIndex]);

  return (
    <ol className="space-y-0">
      {groups.map((group, groupIndex) => {
        const anyLive = groupIndex === liveIndex;

        return (
          <li key={group.start} className="relative">
            {/* sticky time rail — stays pinned while its block scrolls past */}
            <div
              ref={anyLive ? liveRef : undefined}
              id={anyLive ? nowAnchorId : undefined}
              className="sticky top-[var(--agenda-sticky-top,0px)] z-10 -mx-5 flex items-center gap-3 scroll-mt-[calc(var(--agenda-sticky-top,0px)+1rem)] bg-surface/92 px-5 py-2.5 backdrop-blur-md"
            >
              <span className="font-mono text-sm font-semibold tabular-nums text-text">
                {formatTime(group.start, hour12)}
              </span>
              <span aria-hidden className="h-px flex-1 bg-line" />
              {group.sessions.length > 1 && (
                <span className="text-[11px] text-text-subtle">
                  {group.sessions.length} in parallel
                </span>
              )}
              {anyLive && nowMinutes !== null && <LiveBadge />}
            </div>

            <ul className="space-y-2.5 pt-2 pb-5">
              {group.sessions.map((session) => (
                <li key={session.id}>
                  <AgendaRow
                    session={session}
                    status={sessionStatus(index, session, now)}
                    onSelect={onSelect}
                    hour12={hour12}
                  />
                </li>
              ))}
            </ul>
          </li>
        );
      })}
    </ol>
  );
}

function AgendaRow({
  session,
  status,
  onSelect,
  hour12,
}: {
  session: Session;
  status: SessionStatus;
  onSelect: (session: Session) => void;
  hour12: boolean;
}) {
  const { stageById } = useAgenda();
  const stage = session.stageId ? stageById.get(session.stageId) : null;
  const minutes = durationMinutes(session);

  if (session.allStages) {
    return (
      <button
        type="button"
        onClick={() => onSelect(session)}
        className="lane-empty flex min-h-12 w-full items-center justify-center gap-3 rounded-2xl border border-dashed border-line-strong bg-surface-sunken/80 px-4 py-3.5 text-sm font-semibold tracking-wide text-text-muted uppercase transition active:scale-[0.99]"
      >
        {session.title}
        <span className="font-mono text-xs normal-case tabular-nums">
          {formatDuration(minutes)}
        </span>
      </button>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onSelect(session)}
      className={cx(
        // 44px minimum target; the whole row is the target, not just the title
        "block w-full rounded-2xl border border-line/80 border-l-3 border-l-[var(--accent)]",
        "accent-wash p-4 text-left shadow-(--shadow-card) transition",
        "active:scale-[0.99] sm:hover:-translate-y-px sm:hover:shadow-(--shadow-lift)",
        status === "past" && "opacity-60",
        sessionAccent(stageById, session),
      )}
    >
      {/*
        The time is the first thing on the card and the highest-contrast text
        on it. On the source site the only timestamp lived in a left rail that
        scrolled away, so people misread when a session actually ran.
      */}
      <span className="flex items-baseline gap-2">
        <span className="font-mono text-[13px] font-bold tabular-nums text-text">
          {formatTime(session.start, hour12)}–{formatTime(session.end, hour12)}
        </span>
        <span className="font-mono text-[11px] tabular-nums text-text-subtle">
          {formatDuration(minutes)}
        </span>
      </span>

      <span className="mt-1.5 flex flex-wrap items-center gap-1.5">
        <StageBadge session={session} size="sm" />
        {session.format && <FormatBadge format={session.format} />}
      </span>

      <span className="mt-1.5 block text-[15px] leading-snug font-semibold text-balance text-text">
        {session.title}
      </span>

      {session.speakers.length > 0 && (
        <span className="mt-2 flex items-center gap-2">
          <SpeakerStack speakers={session.speakers} max={4} size={22} />
          <span className="clamp-1 text-xs text-text-muted">
            {session.speakers.map((s) => s.name).join(", ")}
          </span>
        </span>
      )}

      <span className="mt-2 flex items-center gap-1.5 text-xs text-text-subtle">
        <PinIcon className="size-3 shrink-0" />
        <span className="clamp-1">{session.location ?? stage?.venue}</span>
      </span>
    </button>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { EventNow, Session } from "agenda-views/headless";
import { useAgenda } from "@/lib/agenda-context";
import {
  durationMinutes,
  formatDuration,
  formatRange,
  sessionStatus,
} from "agenda-views/headless";
import {
  buildIcs,
  calendarAriaLabel,
  downloadIcs,
  googleCalendarUrl,
  icsFilename,
} from "agenda-views/headless";
import { useScrollLock } from "@/hooks/use-agenda";
import {
  ClockIcon,
  CloseIcon,
  FormatBadge,
  LiveBadge,
  PinIcon,
  SpeakerAvatar,
  StageBadge,
  cx,
  sessionAccent,
} from "@/components/ui/agenda-primitives";

const FOCUSABLE =
  'a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex="-1"])';

/** 480 -> "GMT+8", -330 -> "GMT-5:30" */
function formatUtcOffset(minutes: number): string {
  const sign = minutes < 0 ? "-" : "+";
  const abs = Math.abs(minutes);
  const h = Math.floor(abs / 60);
  const m = abs % 60;
  return `GMT${sign}${h}${m ? `:${String(m).padStart(2, "0")}` : ""}`;
}

type Props = {
  session: Session | null;
  now: EventNow | null;
  onClose: () => void;
  hour12: boolean;
};

/**
 * One component, two presentations: a bottom sheet under `sm`, a centred
 * dialog above it. Both are a real modal — focus is trapped, Escape closes,
 * background scroll is locked, and focus returns to the trigger on close.
 */
export function SessionSheet({ session, now, onClose, hour12 }: Props) {
  const index = useAgenda();
  const open = session !== null;
  const panelRef = useRef<HTMLDivElement>(null);
  const restoreRef = useRef<HTMLElement | null>(null);

  useScrollLock(open);

  useEffect(() => {
    if (!open) return;
    restoreRef.current = document.activeElement as HTMLElement | null;
    // focus the panel itself, not the first control — screen readers then read
    // the title before the close button
    panelRef.current?.focus();
    return () => restoreRef.current?.focus?.();
  }, [open]);

  const onKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current) return;
      const nodes = [...panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)];
      if (!nodes.length) return;
      const first = nodes[0];
      const last = nodes[nodes.length - 1];
      const active = document.activeElement;
      if (event.shiftKey && (active === first || active === panelRef.current)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    },
    [onClose],
  );

  if (!session) return null;

  const stage = session.stageId ? index.stageById.get(session.stageId) : null;
  const day = index.dayById.get(session.day);
  const status = sessionStatus(index, session, now);

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center sm:items-center sm:p-6"
      role="presentation"
      onKeyDown={onKeyDown}
    >
      <div
        className="absolute inset-0 bg-ink-950/45 animate-fade-in"
        onClick={onClose}
        aria-hidden
      />

      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="session-sheet-title"
        tabIndex={-1}
        className={cx(
          "animate-sheet-in relative flex max-h-[88dvh] w-full flex-col overflow-hidden",
          "rounded-t-2xl border border-line bg-surface-raised shadow-2xl",
          "sm:max-w-lg sm:rounded-2xl",
          sessionAccent(index.stageById, session),
        )}
      >
        {/* drag affordance — visual only; the sheet closes via backdrop/Esc/button */}
        <div aria-hidden className="flex justify-center pt-2 sm:hidden">
          <span className="h-1 w-9 rounded-full bg-line-strong" />
        </div>

        <div className="flex items-start gap-3 border-b border-line px-5 pt-4 pb-4">
          <div className="min-w-0 flex-1">
            <div className="flex flex-wrap items-center gap-1.5">
              <StageBadge session={session} />
              {session.format && <FormatBadge format={session.format} />}
              {status === "live" && <LiveBadge />}
            </div>
            <h2
              id="session-sheet-title"
              className="mt-2 text-lg leading-snug font-bold text-balance text-text"
            >
              {session.title}
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close session details"
            className="-mr-1 grid size-11 shrink-0 place-items-center rounded-full text-text-muted transition hover:bg-surface-sunken hover:text-text"
          >
            <CloseIcon className="size-4" />
          </button>
        </div>

        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-4">
          <dl className="grid gap-3 text-sm">
            <div className="flex gap-2.5">
              <dt className="sr-only">Time</dt>
              <ClockIcon className="mt-0.5 size-4 shrink-0 text-text-subtle" />
              <dd className="text-text">
                <span className="font-medium">
                  {day?.weekday} {day?.short}
                </span>
                {", "}
                <time dateTime={`${day?.date}T${session.start}`}>
                  {formatRange(session.start, session.end, hour12)}
                </time>
                <span className="text-text-subtle">
                  {" "}
                  · {formatDuration(durationMinutes(session))}
                </span>
                <span className="block text-xs text-text-subtle">
                  {index.agenda.timezone.replace(/_/g, " ")} ({formatUtcOffset(index.agenda.utcOffsetMinutes)})
                </span>
              </dd>
            </div>

            <div className="flex gap-2.5">
              <dt className="sr-only">Location</dt>
              <PinIcon className="mt-0.5 size-4 shrink-0 text-text-subtle" />
              <dd className="text-text">
                {session.location ?? stage?.venue ?? "Venue-wide"}
              </dd>
            </div>
          </dl>

          {session.description && (
            <p className="mt-4 text-sm leading-relaxed text-pretty text-text-muted">
              {session.description}
            </p>
          )}

          {session.speakers.length > 0 && (
            <section className="mt-5">
              <h3 className="text-xs font-semibold tracking-wider text-text-subtle uppercase">
                {session.speakers.length === 1 ? "Speaker" : "Speakers"}
              </h3>
              <ul className="mt-2.5 grid gap-2.5">
                {session.speakers.map((speaker) => (
                  <li key={speaker.name} className="flex items-center gap-3">
                    <SpeakerAvatar speaker={speaker} size={40} />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-semibold text-text">
                        {speaker.name}
                      </span>
                      {speaker.org && (
                        <span className="block truncate text-xs text-text-muted">
                          {speaker.org}
                        </span>
                      )}
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          )}
        </div>

        <div className="grid gap-2 border-t border-line bg-surface-sunken/50 px-5 py-4 pb-[max(1rem,env(safe-area-inset-bottom))]">
          <a
            href={googleCalendarUrl(index, session)}
            target="_blank"
            rel="noopener noreferrer"
            aria-label={calendarAriaLabel(session, hour12)}
            className="flex h-12 w-full items-center justify-center gap-2.5 rounded-xl bg-[var(--color-brand)] text-sm font-semibold text-white shadow-(--shadow-card) transition hover:opacity-90 active:scale-[0.99]"
          >
            <GoogleCalendarIcon className="size-4" />
            Add to Google Calendar
          </a>

          <div className="grid grid-cols-2 gap-2">
            <button
              type="button"
              onClick={() => downloadIcs(icsFilename(session), buildIcs(index, [session]))}
              className="flex h-11 items-center justify-center gap-2 rounded-xl border border-line bg-surface-raised text-[13px] font-semibold text-text-muted transition hover:border-line-strong hover:text-text active:scale-[0.99]"
            >
              <DownloadIcon className="size-3.5" />
              Apple / .ics
            </button>
            <CopyLinkButton sessionId={session.id} />
          </div>
        </div>
      </div>
    </div>
  );
}

function CopyLinkButton({ sessionId }: { sessionId: string }) {
  const [copied, setCopied] = useState(false);

  return (
    <button
      type="button"
      onClick={async () => {
        const url = new URL(window.location.href);
        url.searchParams.set("session", sessionId);
        try {
          await navigator.clipboard.writeText(url.toString());
          setCopied(true);
          setTimeout(() => setCopied(false), 2000);
        } catch {
          window.prompt("Copy this link", url.toString());
        }
      }}
      className="flex h-11 items-center justify-center gap-2 rounded-xl border border-line bg-surface-raised text-[13px] font-semibold text-text-muted transition hover:border-line-strong hover:text-text active:scale-[0.99]"
    >
      <LinkIcon className="size-3.5" />
      {copied ? "Copied" : "Copy link"}
    </button>
  );
}

